import { useEffect, useLayoutEffect, useRef, useState } from 'preact/hooks'
import { t } from '../../i18n'
import { useScrimPress } from './useScrimPress'
import styles from './OpenSourceNotices.module.css'

/**
 * The notices file both editions ship (THIRD_PARTY_NOTICES.md, generated by scripts/generate_notices.mjs), read from
 * the page bundle: one code path on Desktop and Web, a lazy `?raw` chunk loaded when the view opens. No fetch, no
 * command, no second window and no external opener (2.1-Q221).
 */
const loadNotices = (): Promise<string> =>
  import('../../../../../THIRD_PARTY_NOTICES.md?raw').then((module) => module.default)

type Notices = { readonly state: 'loading' } | { readonly state: 'loaded'; readonly text: string } | { readonly state: 'failed' }

/** About's link to the notices view. */
export function OpenSourceNoticesLink({ onOpen, linkRef }: {
  onOpen(): void
  linkRef: { current: HTMLButtonElement | null }
}) {
  return (
    <button ref={linkRef} type="button" className={styles.link} onClick={onOpen}>
      {t('about.notices.link')}
    </button>
  )
}

/**
 * The notices view, shown in place of About inside About's modal layer. Focus moves once, to the text, as the view
 * opens; the text arriving from its chunk moves none. Escape, the backdrop and Close return to About.
 */
export function OpenSourceNotices({ onClose }: { onClose(): void }) {
  const textRef = useRef<HTMLDivElement>(null)
  const [notices, setNotices] = useState<Notices>({ state: 'loading' })
  const scrim = useScrimPress(onClose)
  useLayoutEffect(() => {
    textRef.current?.focus()
  }, [])
  useEffect(() => {
    let open = true
    loadNotices().then(
      (text) => { if (open) setNotices({ state: 'loaded', text }) },
      () => { if (open) setNotices({ state: 'failed' }) },
    )
    return () => { open = false }
  }, [])

  function onKeyDown(event: KeyboardEvent): void {
    if (event.key !== 'Escape') return
    event.preventDefault()
    event.stopPropagation()
    onClose()
  }

  return (
    <div className={styles.overlay} {...scrim}>
      <section
        className={styles.dialog}
        role="dialog"
        aria-modal="true"
        aria-labelledby="open-source-notices-title"
        data-preserve-overlays="true"
        onKeyDown={onKeyDown}
      >
        <h2 id="open-source-notices-title" className={styles.title}>{t('about.notices.link')}</h2>
        <div
          ref={textRef}
          className={styles.body}
          role="region"
          aria-labelledby="open-source-notices-title"
          aria-busy={notices.state === 'loading'}
          tabIndex={0}
        >
          {notices.state === 'failed'
            ? <p className={styles.error} role="alert">{t('about.notices.loadFailed')}</p>
            : <pre className={styles.text}>{notices.state === 'loaded' ? notices.text : ''}</pre>}
        </div>
        <footer className={styles.footer}>
          <button type="button" className={styles.closeButton} onClick={onClose}>
            {t('window.close')}
          </button>
        </footer>
      </section>
    </div>
  )
}
